\begin{equation}\label{eq:TP_x1x2}
	x_1 + x_2 < \tau, 
\end{equation}
\begin{equation}\label{eq:TP_jth_clause_lessthan_tau}
	v_{j_1} + v_{j_2} + v_{j_3} \ge \tau, v_{j_1} + v_{j_2} < \tau, v_{j_1} + v_{j_3} < \tau, \mbox{ and } v_{j_2} + v_{j_3} < \tau. 
